import builtins as _b

_real_pow = _b.pow


def _pow_guard(*args):
    if len(args) == 3 and args[1] < 0:
        raise RuntimeError("pow(a, -1, n) в этой задаче запрещён: используйте свой mod_inverse.")
    return _real_pow(*args)


_b.pow = _pow_guard
_orig_import = _b.__import__
_BANNED = {"sympy", "gmpy2", "numpy", "Crypto", "Cryptodome"}


def _guard(name, *args, **kwargs):
    if name.split(".")[0] in _BANNED:
        raise ImportError("Модуль {} в этой задаче запрещён.".format(name))
    return _orig_import(name, *args, **kwargs)


_b.__import__ = _guard

